type ExecuteV2SqlLogic struct {
	ctx    context.Context
	svcCtx *svc.ServiceContext
	logx.Logger
}

func NewExecuteV2SqlLogic(ctx context.Context, svcCtx *svc.ServiceContext) *ExecuteV2SqlLogic {
	return &ExecuteV2SqlLogic{
		ctx:    ctx,
		svcCtx: svcCtx,
		Logger: logx.WithContext(ctx),
	}
}

// 执行 v2sql 下的 SQL 初始化脚本（供运�?初始化使用）
func (l *ExecuteV2SqlLogic) ExecuteV2Sql(in *platformgame.ExecuteV2SqlRequest) (*platformgame.ExecuteV2SqlResp, error) {

	// Execute a hardcoded SQL string instead of reading files.
	// Change `defaultSQL` to the initialization SQL you want executed.
	const defaultSQL = `-- public.game 定义

-- Drop table

-- DROP TABLE public.game;

CREATE TABLE IF NOT EXISTS public.game ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, game_code varchar(64) NOT NULL, source_game_code varchar(128) NOT NULL, source_id int8 NULL, category_id int8 NOT NULL, provider_id int8 NOT NULL, source_provider_key varchar(128) NULL, provider_key varchar(128) NULL, channel_id int8 NULL, source_name_i18n jsonb NOT NULL, name_i18n jsonb NOT NULL, source_image_url varchar(512) NULL, image_url varchar(512) NULL, source_sort_no int4 NULL, sort_no int4 DEFAULT 0 NOT NULL, supports_embed bool DEFAULT false NOT NULL, supports_redirect bool DEFAULT false NOT NULL, source_status int2 NOT NULL, status int2 DEFAULT 1 NOT NULL, deleted_at timestamptz(3) DEFAULT NULL::timestamp with time zone NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_game_code CHECK ((btrim((game_code)::text) <> ''::text)), CONSTRAINT ck_game_image_url CHECK (((image_url IS NULL) OR (btrim((image_url)::text) <> ''::text))), CONSTRAINT ck_game_name_i18n CHECK (((jsonb_typeof(name_i18n) = 'object'::text) AND (name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_sort_no CHECK ((sort_no >= 0)), CONSTRAINT ck_game_source_game_code CHECK ((btrim((source_game_code)::text) <> ''::text)), CONSTRAINT ck_game_source_image_url CHECK (((source_image_url IS NULL) OR (btrim((source_image_url)::text) <> ''::text))), CONSTRAINT ck_game_source_name_i18n CHECK (((jsonb_typeof(source_name_i18n) = 'object'::text) AND (source_name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_source_status CHECK ((source_status = ANY (ARRAY[1, 2]))), CONSTRAINT ck_game_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT game_pkey PRIMARY KEY (id));
CREATE INDEX IF NOT EXISTS idx_game_category_id ON public.game USING btree (category_id);
CREATE INDEX IF NOT EXISTS idx_game_channel_source_game_code ON public.game USING btree (channel_id, source_game_code) WHERE (channel_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_game_game_code ON public.game USING btree (game_code);
CREATE INDEX IF NOT EXISTS idx_game_provider_id ON public.game USING btree (provider_id);
CREATE INDEX IF NOT EXISTS idx_game_provider_source_game_code_direct ON public.game USING btree (provider_id, source_game_code) WHERE (channel_id IS NULL);
CREATE INDEX IF NOT EXISTS idx_game_source_id_deleted_at ON public.game USING btree (source_id, deleted_at) WHERE (deleted_at IS NULL);


-- public.game_category 定义

-- Drop table

-- DROP TABLE public.game_category;

CREATE TABLE IF NOT EXISTS public.game_category ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, source_id int8 NOT NULL, category_code varchar(64) NOT NULL, source_category_code varchar(128) NOT NULL, source_name_i18n jsonb NOT NULL, name_i18n jsonb NOT NULL, source_sort_no int4 NULL, sort_no int4 DEFAULT 0 NOT NULL, source_status int2 DEFAULT 1 NOT NULL, status int2 DEFAULT 1 NOT NULL, deleted_at timestamptz(3) DEFAULT NULL::timestamp with time zone NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_category_category_code CHECK ((btrim((category_code)::text) <> ''::text)), CONSTRAINT ck_game_category_name_i18n CHECK (((jsonb_typeof(name_i18n) = 'object'::text) AND (name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_category_sort_no CHECK ((sort_no >= 0)), CONSTRAINT ck_game_category_source_category_code CHECK ((btrim((source_category_code)::text) <> ''::text)), CONSTRAINT ck_game_category_source_name_i18n CHECK (((jsonb_typeof(source_name_i18n) = 'object'::text) AND (source_name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_category_source_status CHECK ((source_status = ANY (ARRAY[1, 2]))), CONSTRAINT ck_game_category_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT game_category_pkey PRIMARY KEY (id));
CREATE INDEX IF NOT EXISTS idx_game_category_category_code ON public.game_category USING btree (category_code);
CREATE INDEX IF NOT EXISTS idx_game_category_source_category_code ON public.game_category USING btree (source_category_code);
CREATE INDEX IF NOT EXISTS idx_game_category_source_id_deleted_at ON public.game_category USING btree (source_id, deleted_at) WHERE (deleted_at IS NULL);


-- public.game_channel 定义

-- Drop table

-- DROP TABLE public.game_channel;

CREATE TABLE IF NOT EXISTS public.game_channel ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, source_id int8 NOT NULL, channel_code varchar(64) NOT NULL, source_channel_code varchar(128) NOT NULL, source_name_i18n jsonb NOT NULL, name_i18n jsonb NOT NULL, source_sort_no int4 DEFAULT 0 NOT NULL, sort_no int4 DEFAULT 0 NOT NULL, source_status int2 DEFAULT 1 NOT NULL, status int2 DEFAULT 1 NOT NULL, deleted_at timestamptz(3) DEFAULT NULL::timestamp with time zone NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_channel_channel_code CHECK ((btrim((channel_code)::text) <> ''::text)), CONSTRAINT ck_game_channel_name_i18n CHECK (((jsonb_typeof(name_i18n) = 'object'::text) AND (name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_channel_sort_no CHECK ((sort_no >= 0)), CONSTRAINT ck_game_channel_source_channel_code CHECK ((btrim((source_channel_code)::text) <> ''::text)), CONSTRAINT ck_game_channel_source_name_i18n CHECK (((jsonb_typeof(source_name_i18n) = 'object'::text) AND (source_name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_channel_source_sort_no CHECK ((source_sort_no >= 0)), CONSTRAINT ck_game_channel_source_status CHECK ((source_status = ANY (ARRAY[1, 2]))), CONSTRAINT ck_game_channel_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT game_channel_pkey PRIMARY KEY (id));
CREATE INDEX IF NOT EXISTS idx_game_channel_channel_code ON public.game_channel USING btree (channel_code);
CREATE INDEX IF NOT EXISTS idx_game_channel_source_channel_code ON public.game_channel USING btree (source_channel_code);
CREATE INDEX IF NOT EXISTS idx_game_channel_source_id_deleted_at ON public.game_channel USING btree (source_id, deleted_at) WHERE (deleted_at IS NULL);


-- public.game_provider 定义

-- Drop table

-- DROP TABLE public.game_provider;

CREATE TABLE IF NOT EXISTS public.game_provider ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, source_id int8 NOT NULL, provider_code varchar(64) NOT NULL, source_provider_code varchar(128) NOT NULL, source_name_i18n jsonb NOT NULL, name_i18n jsonb NOT NULL, source_logo_url varchar(512) NULL, logo_url varchar(512) NULL, source_sort_no int4 NULL, sort_no int4 DEFAULT 0 NOT NULL, source_status int2 DEFAULT 1 NOT NULL, status int2 DEFAULT 1 NOT NULL, deleted_at timestamptz(3) DEFAULT NULL::timestamp with time zone NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_provider_logo_url CHECK (((logo_url IS NULL) OR (btrim((logo_url)::text) <> ''::text))), CONSTRAINT ck_game_provider_name_i18n CHECK (((jsonb_typeof(name_i18n) = 'object'::text) AND (name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_provider_provider_code CHECK ((btrim((provider_code)::text) <> ''::text)), CONSTRAINT ck_game_provider_sort_no CHECK ((sort_no >= 0)), CONSTRAINT ck_game_provider_source_logo_url CHECK (((source_logo_url IS NULL) OR (btrim((source_logo_url)::text) <> ''::text))), CONSTRAINT ck_game_provider_source_name_i18n CHECK (((jsonb_typeof(source_name_i18n) = 'object'::text) AND (source_name_i18n <> '{}'::jsonb))), CONSTRAINT ck_game_provider_source_provider_code CHECK ((btrim((source_provider_code)::text) <> ''::text)), CONSTRAINT ck_game_provider_source_status CHECK ((source_status = ANY (ARRAY[1, 2]))), CONSTRAINT ck_game_provider_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT game_provider_pkey PRIMARY KEY (id));
CREATE INDEX IF NOT EXISTS idx_game_provider_provider_code ON public.game_provider USING btree (provider_code);
CREATE INDEX IF NOT EXISTS idx_game_provider_source_id_deleted_at ON public.game_provider USING btree (source_id, deleted_at) WHERE (deleted_at IS NULL);
CREATE INDEX IF NOT EXISTS idx_game_provider_source_provider_code ON public.game_provider USING btree (source_provider_code);


-- public.game_sync_checkpoint 定义

-- Drop table

-- DROP TABLE public.game_sync_checkpoint;

CREATE TABLE IF NOT EXISTS public.game_sync_checkpoint ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, sync_scope varchar(64) NOT NULL, checkpoint_value varchar(255) NOT NULL, remote_total int8 DEFAULT 0 NOT NULL, local_total int8 DEFAULT 0 NOT NULL, created_count int8 DEFAULT 0 NOT NULL, updated_count int8 DEFAULT 0 NOT NULL, deleted_count int8 DEFAULT 0 NOT NULL, failed_count int8 DEFAULT 0 NOT NULL, sync_status int2 DEFAULT 0 NOT NULL, last_error_message text NULL, last_success_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, last_sync_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_sync_checkpoint_checkpoint_value CHECK ((btrim((checkpoint_value)::text) <> ''::text)), CONSTRAINT ck_game_sync_checkpoint_created_count CHECK ((created_count >= 0)), CONSTRAINT ck_game_sync_checkpoint_deleted_count CHECK ((deleted_count >= 0)), CONSTRAINT ck_game_sync_checkpoint_failed_count CHECK ((failed_count >= 0)), CONSTRAINT ck_game_sync_checkpoint_local_total CHECK ((local_total >= 0)), CONSTRAINT ck_game_sync_checkpoint_remote_total CHECK ((remote_total >= 0)), CONSTRAINT ck_game_sync_checkpoint_sync_scope CHECK ((btrim((sync_scope)::text) <> ''::text)), CONSTRAINT ck_game_sync_checkpoint_sync_status CHECK ((sync_status = ANY (ARRAY[0, 1]))), CONSTRAINT ck_game_sync_checkpoint_updated_count CHECK ((updated_count >= 0)), CONSTRAINT game_sync_checkpoint_pkey PRIMARY KEY (id));
CREATE INDEX IF NOT EXISTS idx_game_sync_checkpoint_last_sync_at ON public.game_sync_checkpoint USING btree (last_sync_at DESC);
CREATE INDEX IF NOT EXISTS idx_game_sync_checkpoint_sync_scope ON public.game_sync_checkpoint USING btree (sync_scope);


-- public.sys_currency 定义

-- Drop table

-- DROP TABLE public.sys_currency;

CREATE TABLE IF NOT EXISTS public.sys_currency ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, currency_code varchar(16) NOT NULL, name_i18n jsonb NOT NULL, currency_type int2 NOT NULL, amount_factor int8 NOT NULL, status int2 DEFAULT 1 NOT NULL, sort_no int4 DEFAULT 0 NOT NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_sys_currency_amount_factor CHECK (((amount_factor > 0) AND ((amount_factor)::text ~ '^10*$'::text))), CONSTRAINT ck_sys_currency_currency_code CHECK ((((currency_code)::text = btrim((currency_code)::text)) AND ((currency_code)::text = upper((currency_code)::text)) AND ((currency_code)::text ~ '^[A-Z0-9]{2,16}$'::text))), CONSTRAINT ck_sys_currency_currency_type CHECK ((currency_type = ANY (ARRAY[1, 2]))), CONSTRAINT ck_sys_currency_name_i18n CHECK (((jsonb_typeof(name_i18n) = 'object'::text) AND (name_i18n <> '{}'::jsonb))), CONSTRAINT ck_sys_currency_sort_no CHECK ((sort_no >= 0)), CONSTRAINT ck_sys_currency_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT pk_sys_currency PRIMARY KEY (id), CONSTRAINT uk_sys_currency_currency_code UNIQUE (currency_code));


-- public.game_currency 定义

-- Drop table

-- DROP TABLE public.game_currency;

CREATE TABLE IF NOT EXISTS public.game_currency ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, game_id int8 NOT NULL, currency_id int8 NOT NULL, source_status int2 DEFAULT 1 NOT NULL, status int2 DEFAULT 1 NOT NULL, deleted_at timestamptz(3) DEFAULT NULL::timestamp with time zone NULL, created_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_game_currency_source_status CHECK ((source_status = ANY (ARRAY[1, 2]))), CONSTRAINT ck_game_currency_status CHECK ((status = ANY (ARRAY[1, 2]))), CONSTRAINT game_currency_pkey PRIMARY KEY (id), CONSTRAINT fk_game_currency_currency FOREIGN KEY (currency_id) REFERENCES public.sys_currency(id));
CREATE INDEX IF NOT EXISTS idx_game_currency_currency_id ON public.game_currency USING btree (currency_id);
CREATE INDEX IF NOT EXISTS idx_game_currency_game_currency ON public.game_currency USING btree (game_id, currency_id);`

	if l.svcCtx.DB == nil {
		return &platformgame.ExecuteV2SqlResp{
			Code:    int32(constant.CodeInternalError),
			Message: "database not available",
		}, nil
	}

	if err := l.svcCtx.DB.Exec(defaultSQL).Error; err != nil {
		return &platformgame.ExecuteV2SqlResp{
			Code:    int32(constant.CodeInternalError),
			Message: "execution failed: " + err.Error(),
			Output:  fmt.Sprintf("[ERROR] %v", err),
		}, nil
	}

	return &platformgame.ExecuteV2SqlResp{
		Code:    int32(constant.CodeSuccess),
		Message: "executed",
		Output:  "[OK] executed default SQL",
	}, nil
}
